    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
     * together with its late charge then (none on a correction); the user who opened it or last edited it
     * cannot settle it,
     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
     * above the proof threshold in force on its date (refused before the clerk limit is considered). A
     * SETTLED claim can only be voided by a steward, and only while the sheet's today is at most 7 days
     * after its settlement (its status log's SETTLED date); its frozen figure then leaves every total and
     * is recorded as reversed. A voided claim keeps its number, if it had one. An open of a claim whose due
 * is above the review threshold in force on its date leaves it in REVIEW instead, opened by the user but
 * with no number yet, until a steward reviews it (see {@link #review}); a REVIEW claim can only be voided
 * here. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
        return changeStatus(sheetId, user, claimId, next, null);
    }

    /** Move the claim to {@code next} as {@link #changeStatus(String, String, long, ClaimStatus)} does;
     * a void is given {@code voidReason}, which while the sheet's list of void reasons is not empty must
     * be one on it (see {@link VoidReasonService#refuseUnlisted}), and is kept on the claim. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        Action action = switch (next) {
            case OPEN -> Action.OPEN;
            case SETTLED -> Action.SETTLE;
            case VOID -> Action.VOID;
            default -> null;
        };
        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
        refuseClosed(sheetId, claim.getDueBy());
        if (!claim.getStatus().canBecome(next)
                || ((claim.getStatus() == ClaimStatus.PENDING || claim.getStatus() == ClaimStatus.REVIEW) && next != ClaimStatus.VOID)) {
            throw new ClaimStatusChangeException();
        }
        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
        if (reversing) refuseLateVoid(sheetId, user, claim);
        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String number = claim.getNumber();
        if (next == ClaimStatus.OPEN && overReview(claim, person)) {
            next = ClaimStatus.REVIEW;
            claim.setOpenedBy(user);
        } else if (next == ClaimStatus.OPEN) {
            number = nextNumber(sheetId, claim.getDueBy());
            claim.setOpenedBy(user);
        }
        if (next == ClaimStatus.SETTLED) {
            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
            BigDecimal due = rollup.liveDueOf(claim, figure);
            refuseUnproved(claim, person, due);
            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
            else claim.setSettledDue(due);
        }
        claim.setStatus(next);
        claim.setNumber(number);
        if (next == ClaimStatus.VOID) claim.setVoidReason(reason);
        claims.flush();
        log(user, person, claim);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case REVIEW -> "CLAIM_REVIEW";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT, DELETED -> throw new IllegalStateException();
        };
        if (next == ClaimStatus.SETTLED) {
        claims.flush();
        log(user, person, claim);
        record("CLAIM_REVIEWED", user, person, claim, null);
        record("CLAIM_OPENED", user, person, claim, number);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
     * live figure, which no statement binds while it is PENDING, together with its late charge then).
     * Refused unless the claim is PENDING, when the user is not a steward or opened or last edited the claim, and when it
     * has no proofs and that due is above the proof threshold in force on its date. */
    @Transactional
    public Claim approve(String sheetId, String user, long claimId) {
        Claim claim = lockPending(sheetId, user, claimId);
        if (claim.isOpenedOrEditedBy(user)) throw new ClaimNotStewardException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal figure = rollup.dueOf(claim, person);
        BigDecimal due = rollup.liveDueOf(claim, figure);
        refuseUnproved(claim, person, due);
        claim.setSettledDue(due);
        claim.setStatus(ClaimStatus.SETTLED);
        claims.flush();
        log(user, person, claim);
        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
        notifyWatchers(user, person, claim);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Raise the claim's proofs count by one. Refused when the claim is SETTLED or VOID; a proof leaves
     * the claim's figures alone, so it may be added while the claim is dated in a closed period. */
    @Transactional
    public Claim addProof(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                || claim.getStatus() == ClaimStatus.DELETED) {
            throw new ClaimStatusChangeException();
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        claim.addProof();
        claims.flush();
        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
        return claim;
    }

    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
     * by its person's last statement if that statement included it. Refused unless the claim is
     * PENDING, and when the user is not a steward. */
    @Transactional
    public Claim reject(String sheetId, String user, long claimId, String reason) {
        Claim claim = lockPending(sheetId, user, claimId);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setStatus(ClaimStatus.OPEN);
        claims.flush();
        log(user, person, claim);
        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The statements taken of the people on each sheet. Taking one binds each of the person's claims that
 * counts (OPEN, PENDING or SETTLED, but not an OPEN one deferred on the sheet's today, nor an unbound OPEN or PENDING one dated within one of their holds) to the figure it shows then, and leaves
 * each that does not count unbound;
 * it records the person's due-total then: the sum of what is due on those claims as each shows it, late
 * charges included (a claim with no figure is skipped), at most the sheet's cap. A late charge is never bound: it keeps following
 * the sheet's today.
 * <p>
 * A steward can cancel a person's last statement: the claims it bound become live again (a figure a
 * statement before it bound is not restored), and the person's statement before it is their last again.
 * <p>
 * A statement can also be taken as of an earlier date, of the sheet as it stood then (see
 * {@link #take(String, String, long, LocalDate)}).
 */
@Service
public class StatementService {

    private final StatementRepository statements;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final SettingsService settings;
    private final SheetHistory history;

    public StatementService(StatementRepository statements, ClaimRepository claims,
            PersonRepository people, SheetService sheets, Audit audit, RollupService rollup,
            SettingsService settings, SheetHistory history) {
        this.settings = settings;
        this.history = history;
        this.statements = statements;
        this.claims = claims;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** A statement taken, with the person's claims as it left them, newest first. */
    public record Taken(Statement statement, List<Claim> claims) {
    }

    /** The sheet's statements, each person's as they stand among theirs, oldest first. */
    @Transactional(readOnly = true)
    public List<Statement> list(String sheetId) {
        return statements.findBySheetIdOrderByIdAsc(sheetId).stream().sorted(Statement.ORDER).toList();
    }

    /** Take the person's statement now (see {@link #take(String, String, long, LocalDate)}). */
    @Transactional
    public Taken take(String sheetId, String user, long personId) {
        return take(sheetId, user, personId, null);
    }

    /**
     * Take the person's statement as of {@code asOf}, a date on or before the sheet's today (now when
     * null): it binds their claims that counted at the end of that date to their figures as they stood
     * then — every change made while the sheet's today was on or before it counts, every later one does
     * not, and it stands in for the sheet's today in every figure — and leaves every other claim of theirs
     * unbound. Its date is that date and its due-total that day's. Refused when the date is after the
     * sheet's today, and when the person was not yet on the sheet then.
     */
    @Transactional
    public Taken take(String sheetId, String user, long personId, LocalDate asOf) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        List<Claim> theirs = claims.lockBySheetIdAndPersonId(sheetId, personId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate today = sheets.today(sheetId);
        if (asOf != null && asOf.isAfter(today)) throw new StatementRefusedException("after the sheet's today");
        // What the statement is taken of: the person and their claims as they stood then, with the
        // rates and settings then, the statement's date standing in for the sheet's today.
        Person then = person;
        List<Claim> stood = theirs;
        RollupService.Basis basis = rollup.live(sheetId);
        if (asOf != null) {
            SheetAsOf sheet = history.asOf(sheetId, asOf);
            then = sheet.person(personId).orElseThrow(() -> new StatementRefusedException("not on the sheet then"));
            stood = sheet.claimsOf(personId);
            basis = sheet;
        }
        LocalDate date = basis.today();
        Map<Long, BigDecimal> figures = new HashMap<>();
        for (Claim claim : stood) {
            if (RollupService.countsLive(claim, then, date)) figures.put(claim.getId(), rollup.figureOf(claim, then, basis));
        }
        int counted = figures.size();
        // The person's due-total as shown (the sum of those claims' figures, at most the sheet's cap): n/a
        // when none of their claims has a figure and no rate applies.
        BigDecimal total = rollup.dueTotalOf(stood, then, basis);
        BigDecimal dueTotal = total == null ? null : total.setScale(2, RoundingMode.HALF_EVEN);
        Statement statement = statements.saveAndFlush(new Statement(sheetId, personId, date, dueTotal, counted));
        for (Claim claim : theirs) {
            if (figures.containsKey(claim.getId())) claim.bind(figures.get(claim.getId()), statement.getId());
            else claim.unbind();
        }
        claims.flush();
        List<String> fields = new ArrayList<>(List.of("name=" + person.getName(),
                "due-total=" + (dueTotal == null ? RollupService.NONE : dueTotal.toPlainString()), "claims=" + counted));
        if (asOf != null) fields.add("asof=" + asOf);
        audit.change("STATEMENT", sheetId, user, fields.toArray(String[]::new));
        rollup.recordSince(sheetId, user, before);
        return new Taken(statement, theirs);
    }

    /** Cancel the person's last statement: the claims it bound become live again. Refused when the user is
     * not a steward of the sheet, and when the person has no statement. */
    @Transactional
    public Taken cancelLast(String sheetId, String user, long personId) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new StatementNotStewardException();
        List<Claim> theirs = claims.lockBySheetIdAndPersonId(sheetId, personId);
        Statement last = statements.last(sheetId, personId)
                .orElseThrow(StatementNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        for (Claim claim : theirs) {
            if (claim.isStated() && last.getId().equals(claim.getStatedBy())) claim.unbind();
        }
        claims.flush();
        statements.delete(last);
        statements.flush();
        audit.change("STATEMENT_CANCELLED", sheetId, user, "name=" + person.getName(), "due-total="
                + (last.getDueTotal() == null ? RollupService.NONE : last.getDueTotal().toPlainString()));
        rollup.recordSince(sheetId, user, before);
        return new Taken(last, theirs);
    }
}

