function isFrozen(claim: Claim): boolean {
  return claim.settledDue !== null && (claim.status === 'SETTLED' || claim.status === 'VOID');
}

/** The figure of a claim, in cents: a claim settled at a rate keeps what was due on it then (and once voided); a
 *  claim a statement bound keeps, unless it is PENDING (no statement binds it while it is), the figure it was bound to (null when that was none); otherwise
 *  what is due on its amount at the rate in force on the claim's date of the grade in force
 *  for its person then, rounded as the claim rounds (see roundsHalfUp) — the rate figure alone,
 *  before any late charge or floor (see claimShownCents); null when no rate applies then. A rate saved
 *  forward-only after the claim was added does not apply to it (see ratesFor). */
export function claimDueCents(
  claim: Claim,
  rates: Rate[],
  grades: PersonGrade[],
  rounding: Rounding,
): number | null {
  if (isFrozen(claim) && claim.settledDue !== null) return cents(claim.settledDue);
  if (claim.stated && claim.status !== 'PENDING') return claim.statedDue === null ? null : cents(claim.statedDue);
  const grade = gradeOn(grades, claim.date);
  return grade === null ? null : dueCents(cents(claim.amount), rateOn(ratesFor(rates, claim.added), grade, claim.date), roundsHalfUp(claim, rounding));
}

  /** Whether the claim counts in the live totals: OPEN, PENDING or SETTLED, but not an OPEN claim
   *  deferred on the sheet's today, nor OPEN or PENDING when it is dated within one of its person's
   *  holds, or its person's retirement date is reached on the sheet's today, and no statement binds it
   *  (a PENDING claim is bound by none while it is). */
  private countsLive(claim: Claim, person: Person): boolean {
    return this.countsAs(claim, claim.status, person);
  }

  /** Whether the claim would count in the live totals were its status `status` (see countsLive). */
  private countsAs(claim: Claim, status: ClaimStatus, person: Person): boolean {
    const as = { ...claim, status };
    if (!counts(as)) return false;
    if (!isOpen(as)) return true;
    if (deferred(claim, this.session.today())) return false;
    const bound = claim.stated && status !== 'PENDING';
    const today = this.session.today();
    const retired = person.retiredFrom !== null && today !== null && person.retiredFrom <= today;
    return bound || !(heldOn(person.holds, claim.date) || retired);
  }

